{
  "decline_reason": "",
  "claims": [
    {
      "text": "Under the Manual’s practice, anyone filing an application, notice or request must include an address for service in Australia or New Zealand, subject to the stated exception for International Registrations Designating Australia (IRDAs).",
      "quotes": [
        {
          "ref": "TMM/Part10/6#1",
          "quote": "Every application, notice or request filed (with the exception of International Registrations Designating Australia (IRDAs)) must contain details of an address for service in Australia or New Zealand (subsection 215(5))."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The statutory geographical requirement is that an address for service must be in Australia or New Zealand.",
      "quotes": [
        {
          "ref": "TMA1995/s215(5)",
          "quote": "(5) An address for service must be an address in Australia or New Zealand."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The Manual also identifies trade mark owners and people whose claims to an interest or right in a trade mark are recorded in the Register as people who must supply that address.",
      "quotes": [
        {
          "ref": "TMM/Part2/3/2/3/5",
          "quote": "Section 215 provides that a person making an application, notice or request or the owner of a trade mark, or a person whose claim to an interest or right in a trade mark is recorded in the Register must supply an address for service in Australia or New Zealand."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The address need not be the applicant’s own address: the Manual says it is usually the applicant’s address or that of an intellectual property attorney or solicitor acting as agent.",
      "quotes": [
        {
          "ref": "TMM/Part10/6#1",
          "quote": "Usually the address for service is that of the applicant itself or that of an intellectual property attorney or solicitor who is acting as the applicant's agent."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For an IRDA, the Manual says the holder must provide an Australian or New Zealand address for service if they wish to respond to a provisional refusal.",
      "quotes": [
        {
          "ref": "TMM/Part60/4/9/4/9/2",
          "quote": "The provisional refusal will be sent to the International Bureau and will contain advice that the holder must provide an address for service in Australia or New Zealand if they wish to respond to the provisional refusal."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual also says an IRDA holder should notify an Australian or New Zealand address for service when filing a notice of intention to defend an opposition.",
      "quotes": [
        {
          "ref": "TMM/Part47/3/3/2",
          "quote": "However, as explained above, it is very important that an IRDA holder also provides notification of their address for service in Australia or New Zealand when they file a notice of intention to defend."
        }
      ],
      "authority": "manual"
    }
  ],
